#include <iostream>

void intercambiar(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x = 3, y = 8;
    intercambiar(&x, &y);
    std::cout << x << ' ' << y << '\n'; // 8 3
    return 0;
}

#include <iostream>

int main() {
    int datos[5] = {2, 4, 6, 8, 10};
    int suma = 0;

    for (int* p = datos; p < datos + 5; ++p) {
        suma += *p;
    }

    std::cout << suma << '\n'; // 30
    return 0;
}

